CREATE FUNCTION public.people_terms_at(t uuid,e uuid,d date) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE result jsonb:='{}';r record;BEGIN FOR r IN SELECT values FROM public.hr_employment_terms WHERE tenant_id=t AND employee_id=e AND effective_date<=d ORDER BY effective_date,approved_at,id LOOP result:=result||r.values;END LOOP;RETURN result;END $$;
REVOKE ALL ON FUNCTION public.people_terms_at(uuid,uuid,date) FROM PUBLIC,anon,authenticated;GRANT EXECUTE ON FUNCTION public.people_terms_at(uuid,uuid,date) TO service_role;
CREATE OR REPLACE FUNCTION public.people_person_access(t uuid,e uuid,u uuid) RETURNS boolean LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE v uuid;BEGIN IF NOT public.people_access(t,u) THEN RETURN false;END IF;SELECT COALESCE(NULLIF(public.people_terms_at(t,e,(now() AT TIME ZONE 'Asia/Hong_Kong')::date)->>'venue_id','')::uuid,venue_id) INTO v FROM public.hr_employees WHERE id=e AND tenant_id=t;IF NOT FOUND THEN RETURN false;END IF;RETURN v IS NULL OR public.user_has_venue(u,v) OR public.people_owner(t,u) OR public.is_super_admin(u);END $$;
CREATE FUNCTION public.people_path_access(p text,u uuid) RETURNS boolean LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE parts text[]:=string_to_array(p,'/');BEGIN IF array_length(parts,1)<3 OR parts[1]!~*'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' OR parts[2]!~*'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN RETURN false;END IF;RETURN public.people_documents_access(parts[1]::uuid,u) AND public.people_person_access(parts[1]::uuid,parts[2]::uuid,u);END $$;
REVOKE ALL ON FUNCTION public.people_path_access(text,uuid) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.people_path_access(text,uuid) TO authenticated,service_role;
ALTER POLICY hr_private_read ON storage.objects USING(bucket_id='hr-private-documents' AND public.people_path_access(name,auth.uid()));ALTER POLICY hr_private_upload ON storage.objects WITH CHECK(bucket_id='hr-private-documents' AND public.people_path_access(name,auth.uid()));
CREATE FUNCTION public.people_change_scope(t uuid,e uuid,p jsonb,u uuid) RETURNS boolean LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE v uuid;BEGIN IF NOT public.people_access(t,u) OR (e IS NOT NULL AND NOT public.people_person_access(t,e,u)) THEN RETURN false;END IF;v:=NULLIF(p->>'venue_id','')::uuid;RETURN v IS NULL OR public.people_owner(t,u) OR public.is_super_admin(u) OR public.user_has_venue(u,v);END $$;
REVOKE ALL ON FUNCTION public.people_change_scope(uuid,uuid,jsonb,uuid) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.people_change_scope(uuid,uuid,jsonb,uuid) TO authenticated,service_role;
CREATE POLICY changes_person_restriction ON public.hr_people_changes AS RESTRICTIVE FOR SELECT TO authenticated USING(public.people_change_scope(tenant_id,employee_id,values,auth.uid()));
CREATE FUNCTION public.people_pending_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.people_change_scope(NEW.tenant_id,NEW.employee_id,NEW.values,auth.uid()) THEN RAISE EXCEPTION 'Person and venue access required';END IF;RETURN NEW;END $$;
CREATE TRIGGER people_pending_scope BEFORE INSERT ON public.hr_people_changes FOR EACH ROW EXECUTE FUNCTION public.people_pending_guard();
CREATE FUNCTION public.people_document_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.people_documents_access(NEW.tenant_id,auth.uid()) OR NOT public.people_person_access(NEW.tenant_id,NEW.employee_id,auth.uid()) THEN RAISE EXCEPTION 'Person documents access required';END IF;IF NOT EXISTS(SELECT 1 FROM storage.objects WHERE bucket_id='hr-private-documents' AND name=NEW.storage_path) THEN RAISE EXCEPTION 'Upload the document first';END IF;RETURN NEW;END $$;
CREATE TRIGGER people_document_scope BEFORE INSERT ON public.hr_person_documents FOR EACH ROW EXECUTE FUNCTION public.people_document_guard();
CREATE FUNCTION public.people_project_employee() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE p jsonb;BEGIN p:=public.people_terms_at(NEW.tenant_id,NEW.id,(now() AT TIME ZONE 'Asia/Hong_Kong')::date);NEW:=jsonb_populate_record(NEW,p-'pay_amount'-'pay_basis'-'weekly_hours'-'annual_leave'-'probation_months'-'notice_days');RETURN NEW;END $$;
CREATE TRIGGER people_employee_project BEFORE UPDATE ON public.hr_employees FOR EACH ROW EXECUTE FUNCTION public.people_project_employee();
CREATE OR REPLACE FUNCTION public.people_feature_write_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE row_data jsonb;v uuid;s jsonb;BEGIN row_data:=CASE WHEN TG_OP='DELETE' THEN to_jsonb(OLD) ELSE to_jsonb(NEW) END;SELECT COALESCE(NULLIF(public.people_terms_at((row_data->>'tenant_id')::uuid,(row_data->>'employee_id')::uuid,(now() AT TIME ZONE 'Asia/Hong_Kong')::date)->>'venue_id','')::uuid,venue_id) INTO v FROM public.hr_employees WHERE id=(row_data->>'employee_id')::uuid AND tenant_id=(row_data->>'tenant_id')::uuid;s:=public.people_effective_settings((row_data->>'tenant_id')::uuid,v);IF TG_TABLE_NAME='hr_shifts' AND NOT (s->>'rota')::boolean OR TG_TABLE_NAME='hr_attendance' AND s->>'clock_in'='off' OR TG_TABLE_NAME='hr_leave_requests' AND NOT (s->>'leave_requests')::boolean THEN RAISE EXCEPTION 'This People feature is disabled';END IF;IF TG_OP='DELETE' THEN RETURN OLD;END IF;RETURN NEW;END $$;
CREATE TRIGGER people_shift_delete_gate BEFORE DELETE ON public.hr_shifts FOR EACH ROW EXECUTE FUNCTION public.people_feature_write_guard();CREATE TRIGGER people_clock_delete_gate BEFORE DELETE ON public.hr_attendance FOR EACH ROW EXECUTE FUNCTION public.people_feature_write_guard();CREATE TRIGGER people_leave_delete_gate BEFORE DELETE ON public.hr_leave_requests FOR EACH ROW EXECUTE FUNCTION public.people_feature_write_guard();